import ast
import os

def parse_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        tree = ast.parse(f.read())

    module_name = os.path.basename(filepath).replace('.py', '')
    results = [f"## paket.{module_name}"]

    items = []

    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not node.name.startswith('_'):
                args_list = []
                for arg in node.args.args:
                    arg_str = arg.arg
                    if arg.annotation:
                        arg_str += f": {ast.unparse(arg.annotation)}"
                    if arg.default:
                        arg_str += f" = {ast.unparse(arg.default)}"
                    args_list.append(arg_str)

                prefix = "async " if isinstance(node, ast.AsyncFunctionDef) else ""
                ret_str = f" -> {ast.unparse(node.returns)}" if node.returns else ""
                doc = ast.get_docstring(node)
                doc = doc.split('\n')[0] if doc else ""
                items.append((node.lineno, f"{prefix}{node.name}({', '.join(args_list)}){ret_str}", doc))

        elif isinstance(node, ast.ClassDef):
            if not node.name.startswith('_'):
                doc = ast.get_docstring(node)
                doc = doc.split('\n')[0] if doc else ""
                items.append((node.lineno, f"class {node.name}", doc))

                for subnode in node.body:
                    if isinstance(subnode, (ast.FunctionDef, ast.AsyncFunctionDef)) and not subnode.name.startswith('_'):
                        if subnode.name != '__init__':
                            args_list = []
                            for arg in subnode.args.args:
                                arg_str = arg.arg
                                if arg.annotation:
                                    arg_str += f": {ast.unparse(arg.annotation)}"
                                if arg.default:
                                    arg_str += f" = {ast.unparse(arg.default)}"
                                args_list.append(arg_str)

                            prefix = "async " if isinstance(subnode, ast.AsyncFunctionDef) else ""
                            ret_str = f" -> {ast.unparse(subnode.returns)}" if subnode.returns else ""
                            doc_m = ast.get_docstring(subnode)
                            doc_m = doc_m.split('\n')[0] if doc_m else ""
                            items.append((subnode.lineno, f"{node.name}.{prefix}{subnode.name}({', '.join(args_list)}){ret_str}", doc_m))

    items.sort(key=lambda x: x[0])
    for _, sig, doc in items:
        results.append(f"- `{sig}` — {doc}")

    return "\n".join(results)

print(parse_file("paket/metin.py"))
print("-" * 20)
print(parse_file("paket/sayi.py"))

import ast
import os

def parse_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        tree = ast.parse(f.read())

    module_name = os.path.basename(filepath).replace('.py', '')
    results = [f"## paket.{module_name}"]

    items = []

    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            # Sadece modül düzeyindeki veya sınıf içindeki fonksiyonları/metotları alalım
            # parent kontrolü yapmak için ast.walk yerine döngü ile gitmek daha güvenli
            pass

    # Daha kontrollü bir yürüyüş
    def walk_nodes(parent_node, is_module=False):
        for node in parent_node.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if not node.name.startswith('_'):
                    if not (not is_module and isinstance(parent_node, ast.ClassDef) and node.name == '__init__'):
                        # İmza oluşturma
                        args_list = []
                        # normal args
                        num_defaults = len(node.args.defaults)
                        num_args = len(node.args.args)
                        for i, arg in enumerate(node.args.args):
                            arg_str = arg.arg
                            if arg.annotation:
                                arg_str += f": {ast.unparse(arg.annotation)}"
                            if i >= num_args - num_defaults:
                                default_val = node.args.defaults[i - (num_args - num_defaults)]
                                arg_str += f" = {ast.unparse(default_val)}"
                            args_list.append(arg_str)

                        # kwonlyargs
                        for kwarg in node.args.kwonlyargs:
                            arg_str = kwarg.arg
                            if kwarg.annotation:
                                arg_str += f": {ast.unparse(kwarg.annotation)}"
                            if kwarg.default:
                                arg_str += f" = {ast.unparse(kwarg.default)}"
                            args_list.append(arg_str)

                        prefix = "async " if isinstance(node, ast.AsyncFunctionDef) else ""
                        ret_str = f" -> {ast.unparse(node.returns)}" if node.returns else ""
                        doc = ast.get_docstring(node)
                        doc = doc.split('\n')[0] if doc else ""

                        if isinstance(parent_node, ast.ClassDef):
                            items.append((node.lineno, f"{parent_node.name}.{prefix}{node.name}({', '.join(args_list)}){ret_str}", doc))
                        else:
                            items.append((node.lineno, f"{prefix}{node.name}({', '.join(args_list)}){ret_str}", doc))

            elif isinstance(node, ast.ClassDef):
                if not node.name.startswith('_'):
                    doc = ast.get_docstring(node)
                    doc = doc.split('\n')[0] if doc else ""
                    items.append((node.lineno, f"class {node.name}", doc))
                    walk_nodes(node)

            elif hasattr(node, 'body') and isinstance(node, (ast.Module, ast.ClassDef)):
                walk_nodes(node)

    walk_nodes(tree, True)
    items.sort(key=lambda x: x[0])

    for _, sig, doc in items:
        results.append(f"- `{sig}` — {doc}")

    return "\n".join(results)

