import ast
import os

def generate_api_docs(package_dir):
    files = [f for f in os.listdir(package_dir) if f.endswith('.py') and not f.startswith('_')]
    if os.path.exists(os.path.join(package_dir, '__init__.py')):
        with open(os.path.join(package_dir, '__init__.py'), 'r', encoding='utf-8') as f:
            if f.read().strip():
                # __init__.py boş değilse işleme alınabilir ama kurallar 'boşsa atla' diyor.
                pass

    all_docs = []

    for filename in sorted(files):
        filepath = os.path.join(package_dir, filename)
        with open(filepath, 'r', encoding='utf-8') as f:
            tree = ast.parse(f.read())

        module_name = filename.replace('.py', '')
        module_docs = [f"## paket.{module_name}"]

        items = []

        def get_signature(node):
            args_list = []
            # Normal args
            num_defaults = len(node.args.defaults)
            num_args = len(node.args.args)
            for i, arg in enumerate(node.args.args):
                arg_str = arg.arg
                if arg.annotation:
                    arg_str += f": {ast.unparse(arg.annotation)}"
                if i >= num_args - num_defaults:
                    default_val = node.args.defaults[i - (num_args - num_defaults)]
                    arg_str += f" = {ast.unparse(default_val)}"
                args_list.append(arg_str)
            # Keyword only args
            for arg in node.args.kwonlyargs:
                arg_str = arg.arg
                if arg.annotation:
                    arg_str += f": {ast.unparse(arg.annotation)}"
                if arg.default:
                    arg_str += f" = {ast.unparse(arg.default)}"
                args_list.append(arg_str)

            prefix = "async " if isinstance(node, ast.AsyncFunctionDef) else ""
            ret_str = f" -> {ast.unparse(node.returns)}" if node.returns else ""
            return f"{prefix}{node.name}({', '.join(args_list)}){ret_str}"

        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                if not node.name.startswith('_'):
                    doc = ast.get_docstring(node)
                    doc = doc.split('\n')[0] if doc else ""
                    items.append((node.lineno, f"{get_signature(node)}", doc))
            elif isinstance(node, ast.ClassDef):
                if not node.name.startswith('_'):
                    doc = ast.get_docstring(node)
                    doc = doc.split('\n')[0] if doc else ""
                    items.append((node.lineno, f"class {node.name}", doc))
                    for subnode in node.body:
                        if isinstance(subnode, (ast.FunctionDef, ast.AsyncFunctionDef)) and not subnode.name.startswith('_'):
                            if subnode.name != '__init__':
                                doc_m = ast.get_docstring(subnode)
                                doc_m = doc_m.split('\n')[0] if doc_m else ""
                                items.append((subnode.lineno, f"{node.name}.{get_signature(subnode)}", doc_m))

        items.sort(key=lambda x: x[0])
        for _, sig, doc in items:
            module_docs.append(f"- `{sig}` — {doc}")
        all_docs.append("\n".join(module_docs))

    return "\n\n".join(all_docs)

if __name__ == "__main__":
    print(generate_api_docs("paket"))

